import{_ as e,o as a,c as t,ag as _}from"./chunks/framework.DaAXJYxM.js";const m=JSON.parse('{"title":"第25章 走廊","description":"","frontmatter":{},"headers":[],"relativePath":"第25章_走廊.md","filePath":"第25章_走廊.md"}'),r={name:"第25章_走廊.md"};function o(n,p,s,c,i,d){return a(),t("div",null,[...p[0]||(p[0]=[_('<h1 id="第25章-走廊" tabindex="-1">第25章 走廊 <a class="header-anchor" href="#第25章-走廊" aria-label="Permalink to &quot;第25章 走廊&quot;">​</a></h1><p>我们班在三楼东边，她们班在二楼西边。</p><p>这两个位置基本是两个方向。从我们教室门口走到她们教室门口，要先出后门，走到连廊，下一层楼，再走到西头。快走是两分半，慢走四分钟。课间十分钟，来回五分钟，中间剩五分钟。</p><p>五分钟能干什么，什么都干不了。</p><p>所以我找到了另一个办法：绕路。</p><p>我们学校有两部楼梯，东边一部，西边一部。正常从三楼到食堂，走东边那部，下到一楼直接出门。我不走东边。我走西边。</p><p>走西边要多走一段，经过二楼的那条走廊。她们班的门在走廊中间，门旁边有一块公告板，板上贴着各种通知。</p><p>我每天下去两次。一次是上午最后一节课下课，一次是下午最后一节课下课。走那条走廊的时候我会放慢一点，大概慢两秒。两秒足够我往门里看一眼。</p><p>这两秒是我自己定的规矩。不快不慢，太慢了显眼，太快了看不到。我试了几天才找到这个速度。</p><p>后来这个动作变成了我一天里最要紧的一件事。中午那节课下课前五分钟我就开始看表，看老师什么时候放人。</p><p>门一般是关着的。</p><p>她们班的门上课的时候关，下课的时候开。开的时候我能看见里面的角度很窄，最多看到第一排和第二排。</p><p>她坐在第四排。我一次都没看见过。</p><p>但我还是每次都走那边。</p><p>有一天走那条路的时候，有人叫住我。</p><p>是她们班一个男生，抱着一个题本，站在门口，问我：同学，三楼往哪边走。</p><p>我指了方向。</p><p>他说了谢谢，转身进去了。进去的时候门开得大了一点，我看见里面坐着的人。第一排靠窗的位置，坐着一个女生，正低头写着什么。</p><p>那不是她。</p><p>我又走了两步，才反应过来自己在干什么。我在一个跟我没有关系的地方，找一个我认得的人。</p><p>那天晚上我跟她说，我今天走你们班门口了。</p><p>她说，我知道。</p><p>我说，你怎么知道。</p><p>她说，我看见了。</p><p>我说，你坐在第四排，门开的时候看不到。</p><p>她说，我看得到。</p><p>她说，你走路的样子跟别人不一样。</p><p>我问，哪不一样。</p><p>她说，你说不上来。</p><p>她说，你走路不摆胳膊。</p><p>我把这句话记下来了。我后来走路的时候会有意地摆一下胳膊，摆了两天又忘了。</p><p>十月中旬，她提出了一件事。</p><p>她说，你能不能别老走那条路。</p><p>我说，为什么。</p><p>她说，有一天我们班主任站在门口，他看了你一眼。</p><p>我说，看一眼怎么了。</p><p>她说，他记性好。</p><p>我说，我又没干什么。</p><p>她说，你走那边两天了。</p><p>我这才知道她也一直在数。我走那条走廊的次数，她数的比我还清楚。</p><p>我说，好。</p><p>她说，你别老说好。</p><p>我说，那我该说什么。</p><p>她说，你什么都别说。</p><p>那条路我确实不走了。我改回东边那部楼梯，正常走。</p><p>但我又找到了一条路。</p><p>三楼的西边有一个天井，天井旁边的栏杆能看到二楼的走廊。从那个位置，能看到她们班门口的一段。我每天晚自习之前会绕到那里站两分钟。</p><p>站着干不了什么，就是看一眼。那条走廊上人来人往，有时候能看见她从教室里出来，往洗手间去，五分钟之后回来。</p><p>有一次下雨，天井里积了水。晚自习之前那段时间天已经暗了，走廊上的灯管只有一半亮，光一条一条的。</p><p>那天她从教室里出来，在门口站了一会儿。我以为她要往洗手间去，结果她没往那边走，而是靠着墙站在原地。</p><p>她站了大概两分钟，一直看着楼下的操场。然后她转身回去了。</p><p>我不知道那两分钟她在想什么。我站在楼上，也一句话没说。</p><p>我隔着一层楼，看着她走过去，走回来。</p><p>有一次她走到一半停了下来。她抬头看了一下。</p><p>我往后站了一步，退到栏杆后面。</p><p>那天晚上她发消息说：今天你是不是站在楼上。</p><p>我说，没有。</p><p>她说，我看到了一个人影。</p><p>我说，可能是别人。</p><p>她说，别人不会站在那儿。</p><p>我没回。</p><p>隔了一会儿，她发来一句。</p><p>她说，你站那儿，我不生气。</p><p>我说，那你还问我。</p><p>她说，我就是想问。</p><p>她说，你看了多久了。</p><p>我说，两天。</p><p>她说，你说谎。</p><p>我说，三天。</p><p>她说，你这个人。</p><p>她说，以后你要看，就站着看。</p><p>她说，别躲。</p><p>那天之后我站那里就不躲了。</p><p>她出来的时候有时候会抬头看一眼。她不笑，也不招手，就是看一眼，然后继续往前走。走完那一段她进教室，门关上，我也下楼去上晚自习。</p><p>这大概是我们之间最像样的一件事。隔着两层楼和一条走廊，她走过去，他看一眼。不需要说话，不需要递东西，不需要找理由。</p><p>我后来把这个地方记下了。我在本子上给那根栏杆定了个名字。</p><p>叫“老地方”。</p><p>这个名字后来用了很久。一直到第二个学期，一直到她换教室，一直到那件事发生之前。</p><p>那地方其实没什么特别的。一根水泥栏杆，栏杆外面是一片天井，底下是水泥地，一下雨就积水。</p><p>可在那里站着的那几百个傍晚，我都记得。</p><p>可我后来想，那也挺可悲的。</p><p>我们两个人，用了整整一个学期，就学会了这么一件事：怎么在不让任何人发现的情况下，看见对方一眼。</p><p>可有一次不一样。</p><p>那是十一月的一天，下着雨。我在栏杆那边站着，她出来了。</p><p>她抬头看了一眼我那个位置。</p><p>然后她站住了。她没走。她就站在那里，看着我站的地方，站了很久。</p><p>走廊里有人从她身边走过去，有人进了教室。她一直站着。</p><p>我站在楼上，也一动不动。</p><p>我们隔着两层楼看着对方。中间有雨声，有楼梯间的声音，有其他班教室里的读书声。</p><p>那大概有一分钟。也可能只有三十秒。</p><p>然后她低下了头，转身进了教室。</p><p>那天晚上她什么都没说。我也没问。</p><p>可我从那天起知道了一件事：她也和我一样，在盼着看一眼。</p>',93)])])}const f=e(r,[["render",o]]);export{m as __pageData,f as default};
